--liquibase formatted sql
--changeset id:00001 author:edwgiz@gnail.com

create type nutrient_status_enum as enum ('active', 'disabled', 'archived');

create table nutrient
(
    id              uuid                 not null primary key,
    parent_id       uuid                 not null
        constraint fk_nutrient__nutrient references nutrient,
    fdc_nutrient_id integer              not null unique,
    nutrient_nbr    numeric(6, 2) unique,
    status          nutrient_status_enum not null default 'disabled',
    sort_order      smallint             not null default 32767,
    name            varchar(255)         not null,
    description     text                 not null
);

comment on column nutrient.nutrient_nbr is 'A unique code identifying a nutrient or food constituent';

create table nutrient_link
(
    id           uuid not null primary key,
    nutrition_id uuid not null
        constraint fk_nutrient_link__nutrient references nutrient,
    url          text,
    title        varchar(255)
);

insert into nutrient (id,parent_id,fdc_nutrient_id,nutrient_nbr, status, sort_order, name,description) values ('ffffffff-ffff-ffff-ffff-ffffffffffff', 'ffffffff-ffff-ffff-ffff-ffffffffffff', -1, null, 'disabled',  0, 'Void', 'The parent for unused nutrients');
insert into nutrient (id,parent_id,fdc_nutrient_id,nutrient_nbr, status, sort_order, name,description) values ('00000000-0000-0000-0000-000000000000', 'ffffffff-ffff-ffff-ffff-ffffffffffff', 0, null, 'disabled', 0, 'Root', 'Root nutrient class including the all others');

